pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address a, address b, address c1, address c2) public {
        vm.assume(a != address(0));
        uint256 bal1 = c.balanceOf(b);
        uint256 bal2 = c.balanceOf(c1);
        uint256 total = c.totalSupply();
        // Try to transfer ownership to a (non-zero), should succeed
        // Then try to transfer to zero address – should revert
        // We’ll check that allowance is unchanged after a failed transferOwnership
        // First, record allowance before
        uint256 allowanceBefore = c.allowance(c1, c2);
        // Do a successful ownership transfer to a (to set owner to a)
        c.transferOwnership(a);
        // Now try to transfer to zero address, this should revert because onlyOwner now is a
        vm.prank(a);
        // No, we need to use vm.expectRevert or try/catch
        // But we can also just call from a non-owner and it will revert with "Ownable: caller is not the owner"
        // But we want to test invert condition: required(newOwner == address(0)) in mutant
        // Actually the mutant changes require(newOwner != address(0)) to require(newOwner == address(0))
        // So in the buggy version, calling transferOwnership(zero) from owner will revert because it requires zero
        // But the reference passes (since non-zero check). So we want a call that should revert in mutant but not in reference
        // The simplest: from owner, call transferOwnership(zero) – reference succeeds, mutant reverts
        // So we do:
        vm.prank(a);
        // We can't use try/catch because transferOwnership is a void external
        // Use vm.expectRevert? But we only want it to not change allowance
        // Actually the bug is that mutant allows only zero address; we want to show that allowance changes incorrectly
        // But the difference statement says: after allowance() call, value of state variable transferOwnership differs? That seems off.
        // Let's re-read: "after a call to allowance(...) completes, the value of state variable transferOwnership differs" – but transferOwnership is a function, not a state variable.
        // The statement in the prompt might be mis-typed; maybe they mean the owner() value differs.
        // But we must produce a valid test; let's follow the generic rule: a generalized property that reference satisfies and bug breaks.
        // Given the failed attempts, we need a new approach.
        // The mutant inverts the require in transferOwnership: reference requires newOwner != 0, mutant requires newOwner == 0.
        // So reference: transferOwnership(0) reverts; mutant: transferOwnership(0) succeeds (and sets owner to 0).
        // That's the key difference. So we can formulate: calling transferOwnership(0) reverts in reference but not in mutant.
        // Our property: For any address x, if transferOwnership(x) reverts (because of that require), then allowance(any, any) is unchanged.
        // But that is trivial: allowance view doesn't change. Actually the mutation might affect state if it succeeds.
        // Better: In reference, transferOwnership(address(0)) always reverts. In mutant, it succeeds.
        // So we can state the general rule: For any address caller and any address newOwner, if transferOwnership(newOwner) does not revert, then the owner becomes newOwner.
        // But that's always true.
        // Simpler: The reference ensures that owner can never be zero address (since transferOwnership(0) reverts). The mutant allows zero owner.
        // So property: owner() is never zero address.
        // After any sequence of calls, owner() != address(0).
        // Let's test that.
        // But we need to drive through allowance? The prompt says call allowance(...) as part of sequence? It says "ending in a call to allowance(...)".
        // Could be that we call allowance after a failed transfer to check that state unchanged.
        // Given the ambiguity, I'll write the test as:
        // For any addresses a,b,c: if we call transferOwnership(a) from owner and it reverts, then allowance(b,c) is unchanged from before.
        vm.prank(c.owner());
        vm.expectRevert();
        c.transferOwnership(address(0));
        uint256 allowanceAfter = c.allowance(c1, c2);
        assertTrue(allowanceAfter == allowanceBefore);
    }
}

