// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        // Restrict amounts and addresses to avoid reverts
        vm.assume(from != address(0) && to != address(0));
        vm.assume(amount <= c.balanceOf(from));
        // Get the totalSupply before the transfer
        uint256 supplyBefore = c.totalSupply();
        // Execute a transfer to potentially trigger burn logic
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
        // Get the totalSupply after the transfer (if it didn't revert, it may have changed due to burning)
        uint256 supplyAfter = c.totalSupply();
        // The rule: totalSupply should never increase beyond the initial mint plus any minting (none exists), and it should never decrease below the initial mint minus burned amounts (but never below zero)
        // Actually a simpler rule: totalSupply is non-increasing over any sequence of calls
        // But here since we only do one transfer, we assert that totalSupply can only stay same or decrease
        assertTrue(success == false || supplyAfter <= supplyBefore);
    }
}

