pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(from != address(0) && to != address(0) && from != to);
        vm.assume(amount > 0 && amount <= type(uint256).max / 10);

        // Get initial total supply
        uint256 initialTotal = c.totalSupply();

        // Setup: ensure from has some balance by transferring from owner
        address owner = address(this);
        uint256 ownerBalance = c.balanceOf(owner);
        if (ownerBalance > 0) {
            vm.prank(owner);
            c.transfer(from, amount);
        }

        // Perform the transfer that might change supply
        uint256 preTransferSupply = c.totalSupply();
        vm.prank(from);
        (bool success,) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
        uint256 postTransferSupply = c.totalSupply();

        // Rule: totalSupply must never increase due to a transfer
        assertTrue(postTransferSupply >= preTransferSupply, "totalSupply decreased");
    }
}

