pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(from != address(0) && to != address(0) && from != to);
        vm.assume(from != address(c) && to != address(c));
        amount = bound(amount, 1, 1_000_000 * 1e18);

        // Mint initial tokens to from
        address[] memory users = new address[](1);
        users[0] = from;
        c.setWhiteBulk(users, true);

        // Record balances before transfer
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceFromBefore = c.balanceOf(from);
        uint256 balanceToBefore = c.balanceOf(to);

        // Try transfer - may revert due to blacklist or other checks
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));

        if (success) {
            uint256 supplyAfter = c.totalSupply();
            uint256 balanceFromAfter = c.balanceOf(from);
            uint256 balanceToAfter = c.balanceOf(to);
            // Total supply must be at least the sum of any two balances
            assertTrue(supplyAfter >= balanceFromAfter + balanceToAfter);
        }
    }
