// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        // Restrict to avoid reverts: from must have some tokens, to must not be zero, amount <= balance
        vm.assume(from != address(0) && to != address(0) && from != to);
        // Mint tokens to from by transferring from owner (address(this)) to from via the contract's internal supply
        // The owner has the initial supply; we need from to have a balance to transfer.
        // We'll use vm.prank to simulate a whitelisted transfer (address(this) is whitelisted)
        vm.assume(amount > 0 && amount <= 1000000 * 1e18); // bound amount

        // Record total supply before any transfer
        uint256 totalSupplyBefore = c.totalSupply();

        // Perform a transfer from a whitelisted address (address(this)) to 'from' to give 'from' tokens
        vm.prank(address(this));
        c.transfer(from, amount);

        // Now transfer from 'from' to 'to' (both not whitelisted, so it will trigger fee logic if to == pairAddress, but we avoid that)
        // To avoid reverts due to blacklist or pair address, skip if from or to is the pair address
        vm.assume(from != c.pairAddress() && to != c.pairAddress());
        vm.assume(!c.blackAddress(from) && !c.blackAddress(to));

        // Give whiteAddress status to from and to to avoid fee? Actually we need a rule that holds regardless.
        // The bug: totalSupply returns 0, so after transfers, totalSupply would be 0 even though tokens exist.
        // A general rule: totalSupply does not decrease below a lower bound after any transfer.
        // Simpler: total supply should be >= initial total supply after any sequence of transfers? Not true due to burning.
        // Let's use the distribution function to test: distributing tokens reduces totalSupply? No, it just transfers.
        // Actually the bug is that totalSupply always returns 0. So after any operation, totalSupply should be > 0 if supply was > 0.
        // But the only function that changes totalSupply is _mint (constructor) and _burn (in burnPair).
        // Since burnPair is only called on sells to pairaddress (which we avoid), totalSupply should stay > 0.
        // So we assert: after any transfer, totalSupply > 0 (since it's a positive constant).

        vm.prank(from);
        c.transfer(to, amount);

        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyAfter > 0, "Total supply should be positive after transfers");
    }
}

