pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to) public {
        vm.assume(from != address(0) && to != address(0));
        vm.assume(from != to);
        vm.assume(!c.whiteAddress(from) && !c.whiteAddress(to));
        // Set from as blacklisted, to as not blacklisted
        c.setBlack(from, true);
        c.setBlack(to, false);
        // Mint some tokens to from to enable transfer
        c.setWhite(from, true);
        vm.prank(from);
        c.approve(address(c), 1000);
        c.transferFrom(address(this), from, 1000);
        c.setWhite(from, false);
        // Attempt a transfer from a blacklisted address to a non-blacklisted address
        // This should revert in the reference contract due to blacklist check
        // But the mutant returns 0 for totalSupply, so after a successful transfer we check totalSupply
        // To avoid revert, we use try/catch
        bool reverted;
        try c.transferFrom(from, to, 1) { reverted = false; } catch { reverted = true; }
        // If the transfer succeeded (should not happen in reference), check that totalSupply is not zero
        assertTrue(!reverted || c.totalSupply() > 0);
    }
}

