pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address another, uint256 amount) public {
        vm.assume(owner != address(0));
        vm.assume(another != address(0));
        vm.assume(owner != another);
        vm.assume(amount < 1000000 * 1e18);

        // Ensure owner has enough balance (mint via controlling owner)
        // We cannot mint directly, so we restrict to owner being the deployer (address(this))
        vm.assume(owner == address(this));

        uint256 balanceOwnerBefore = c.balanceOf(owner);
        uint256 balanceAnotherBefore = c.balanceOf(another);
        uint256 sumBefore = balanceOwnerBefore + balanceAnotherBefore;

        // Transfer from owner to another
        if (amount <= balanceOwnerBefore) {
            vm.prank(owner);
            c.transfer(another, amount);
        }

        uint256 balanceOwnerAfter = c.balanceOf(owner);
        uint256 balanceAnotherAfter = c.balanceOf(another);
        uint256 sumAfter = balanceOwnerAfter + balanceAnotherAfter;

        assertTrue(sumBefore == sumAfter, "Sum of balances should remain constant after transfer");
    }
}

