import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address spender, uint256 amount) public {
        // Bound amount to a reasonable value (<= total supply)
        amount = bound(amount, 0, c.totalSupply());

        // Ensure owner has tokens if we want to approve spending
        // For the rule to be general, we just need any approval to be set and then check

        // We'll use the deployer (this contract) as the msg.sender for approvals
        // First, we need to make sure the owner has some tokens to approve (if owner is not the deployer)
