        // Approve the spender from the owner
        vm.prank(owner);
        c.approve(spender, amount);

        // Now check the allowance: it must equal the approved amount, not 0
        uint256 returnedAllowance = c.allowance(owner, spender);
        assertTrue(returnedAllowance == amount, "allowance should return the actual approved amount");
    }
}

