    }

    function testFuzz_property(uint256 amount) public {
        // Bound amount to ensure it doesn't exceed alice's balance
        vm.assume(amount > 0 && amount <= 1000e18);

        // Get allowance before transfer
        uint256 allowanceBefore = c.allowance(alice, bob);

        // Bob executes transferFrom from alice to deployer
        vm.prank(bob);
        bool success = c.transferFrom(alice, deployer, amount);

        // Get allowance after transfer
        uint256 allowanceAfter = c.allowance(alice, bob);

        // Since allowance is infinite, it should remain type(uint256).max
        // The reference returns true, the mutant returns false, but both should not change allowance
        // However the rule: if transferFrom returns true, allowance must not decrease from infinite.
        // For reference: always true, so allowance unchanged. For mutant: returns false, but still the operation did happen (allowance unchanged).
        // But we want a rule that holds for reference and fails for mutant.
        // The mutant's false return violates the expectation that a successful call returns true.
        // So the rule: the call must succeed (return true) when the math is correct.
        assertTrue(success, "transferFrom must return true for valid transfer with sufficient allowance");
    }
}

